head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF91600";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf91600.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_15", fn: function(){ return ((dma_reqCkMap.get("delCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.delCnt"); })()) > 0); } }, { id: "c_when_20", fn: function(){ return ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'Y'); } }, { id: "c_when_25", fn: function(){ return ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'D'); } }, { id: "c_when_30", fn: function(){ return ((dma_map.get("activYn") ?? (() => { throw new Error("unresolved:" + "map.activYn"); })()) !== 'Y'); } }, { id: "c_when_35", fn: function(){ return ((dma_map.get("activTpCd") ?? (() => { throw new Error("unresolved:" + "map.activTpCd"); })()) !== 'Y'); } }, { id: "c_otherwise_40", fn: function(){ return (!(((dma_reqCkMap.get("delCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.delCnt"); })()) > 0) || ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'Y') || ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'D') || ((dma_map.get("activYn") ?? (() => { throw new Error("unresolved:" + "map.activYn"); })()) !== 'Y') || ((dma_map.get("activTpCd") ?? (() => { throw new Error("unresolved:" + "map.activTpCd"); })()) !== 'Y'))); } }, { id: "c_when_13", fn: function(){ return (!(String(((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })())) == null ? '' : ((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()))).length === 0) && (dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()) === (dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })())); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_stdcdType", fn: function () { return String((dma_pageContext.get("stdcdType") ?? "")); } },
        { childId: "ipt_stdCd", fn: function () { return String((dma_pageContext.get("stdCd") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.setComma();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91600.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_goModify_onclick
 * @description btn_goModify 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goModify_onclick = async function(e){
    try {
        await scwin.go_modify()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf91600.btn_goModify_onclick' }); }
};

/**
 * @method
 * @name btn_goDelete_onclick
 * @description btn_goDelete 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goDelete_onclick = function(e){
    try {
        scwin.go_delete()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91600.btn_goDelete_onclick' }); }
};

/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_print_onclick = async function(e){
    try {
        await scwin.print()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf91600.btn_print_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91600.btn_self_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_print
 * @description print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name setComma
 * @description set Comma 처리
 * @returns {void}
 * @hidden N
 */
scwin.setComma = function () {
    $c.util.getComponent('ipt_isuShrs').setValue($c.num.formatNumber($c.util.getComponent('ipt_isuShrs').getValue()));
    $c.util.getComponent('ipt_wrntIsuRnd').setValue($c.num.formatNumber($c.util.getComponent('ipt_wrntIsuRnd').getValue()));
    $c.util.getComponent('ipt_stkRelCorpbndExerPrc').setValue($c.num.formatNumber($c.util.getComponent('ipt_stkRelCorpbndExerPrc').getValue()));
    // TODO Stage2(규칙 19): jQuery — DOM 조립/삭제 → 컴포넌트 setValue/DataList/그리드
    $('#isu_shrs_td').text($c.util.getComponent('ipt_isuShrs').getValue());
    $c.util.getComponent('txt_wrntIsuRndTd').setLabel($c.util.getComponent('ipt_wrntIsuRnd').getValue());
    // TODO Stage2(규칙 19): jQuery — DOM 조립/삭제 → 컴포넌트 setValue/DataList/그리드
    $('#stk_rel_corpbnd_exer_prc_td').text($c.util.getComponent('ipt_stkRelCorpbndExerPrc').getValue());
};

/**
 * @method
 * @name open_modify
 * @description open modify 처리
 * @returns {void}
 * @hidden N
 */
scwin.open_modify = function () {
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF91600 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue("mod");
    fn_passwordWin(form);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_passwordWin — JSP 팝업(window.open+폼 제출 — 회신)
};

/**
 * @method
 * @name open_delete
 * @description open delete 처리
 * @returns {void}
 * @hidden N
 */
scwin.open_delete = function () {
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF91600 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue("del");
    fn_passwordWin(form);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_passwordWin — JSP 팝업(window.open+폼 제출 — 회신)
};

/**
 * @method
 * @name go_modify
 * @description go modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.go_modify = async function () {
    const fm = (document.JLDINF91600 || { elements: [] });
    const url = "/stdcd/stdcdModify.do?method=stdcdModify&type=55&std_cd=" + $c.util.getComponent('ipt_stdCd').getValue();
    fm.action = url;
    fm.target = "_top";
    await moveUrl(url, {});
};

/**
 * @method
 * @name go_delete
 * @description go delete 처리
 * @returns {void}
 * @hidden N
 */
scwin.go_delete = function () {
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF91600 || { elements: [] });
    fn_stdCdDelWin(form);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_stdCdDelWin — JSP 팝업(window.open+폼 제출 — 회신)
    $c.win.closePopup();
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function () {
    if (!await $c.win.confirm("신주인수권증서 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const std_cd = $c.util.getComponent('dma_printReq').get('stdCd');
        $.ajax({ type: "POST", async: false, url: "/srch/srch.do?method=srchReportCommonAjax&serviceName=srchReport55&std_cd=" + std_cd, data: {  }, success: async function(data) {
                    const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                    const form = (document.newReportForm || { elements: [] });
                    for (key in result) {
                        if (form[camelize(key)]) {
                            form[camelize(key)].value = result[key];
                        }
                    }
                    await scwin.tx_fn_print();
                }, error: async function(request, status, error) {
                    await $c.win.alert("장애발생.");
                    return;
                }, complete: function() {

                } });
    }
};

/**
 * @method
 * @name printOld
 * @description print Old 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.printOld = async function () {
    if (!await $c.win.confirm("신주인수권증서 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const std_cd = $c.util.getComponent('dma_printReq').get('stdCd');
        const rexName = "JLDINF91600";
        const dataType = "XML";
        const dataLocation = "/srch/srch.do?method=srchReport55&std_cd=" + std_cd;
        const dataXPath = "main/rpt1";
        const mktGubun = "1";
        fn_PrintPreView_DB(rexName, dataType, dataLocation, dataXPath);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_PrintPreView_DB — 외부 리포트 도구(rexpert)
    }
};
